mapper.select:
SELECT COUNT(*) FROM (
    SELECT pi.id
    FROM t_ds_process_instance pi
    LEFT JOIN t_ds_task_instance ti
    ON pi.id = ti.process_instance_id
    WHERE 1=1

        AND ti.start_time  >= DATE_SUB(NOW(), INTERVAL #{intervalDay} DAY)


        AND ti.start_time  >= DATE_SUB(NOW(), INTERVAL #{intervalMinutes} MINUTE)


        AND pi.name LIKE CONCAT('%', #{processInstanceName}, '%')


        AND pi.start_time BETWEEN #{startTime} AND #{endTime}


        AND pi.start_time  >= #{startTime}


        AND pi.end_time <= #{endTime}


        AND pi.state = #{state}

    GROUP BY pi.id, pi.name, pi.start_time, pi.end_time, pi.state
) AS temp

SELECT pi.id as processInstanceId, pi.name AS processInstanceName, COUNT(DISTINCT ti.task_code) AS taskCount, pi.start_time as startTime, pi.end_time as endTime, pi.state as state FROM t_ds_process_instance pi LEFT JOIN t_ds_task_instance ti ON pi.id = ti.process_instance_id WHERE 1=1
AND ti.start_time >= DATE_SUB(NOW(), INTERVAL #{intervalDay} DAY)
AND ti.start_time >= DATE_SUB(NOW(), INTERVAL #{intervalMinutes} MINUTE)
AND pi.name LIKE CONCAT('%', #{processInstanceName}, '%')
AND pi.start_time BETWEEN #{startTime} AND #{endTime}
AND pi.start_time >= #{startTime}
AND pi.end_time <= #{endTime}
AND pi.state = #{state}
GROUP BY pi.id, pi.name, pi.start_time, pi.end_time, pi.state ORDER BY pi.start_time DESC LIMIT #{pageSize} OFFSET #{offset}

SELECT
    COUNT(*) AS taskCount
FROM t_ds_task_instance ti
WHERE 1=1

    AND ti.start_time  >= DATE_SUB(NOW(), INTERVAL #{intervalDay} DAY)


    AND ti.start_time  >= DATE_SUB(NOW(), INTERVAL #{intervalMinutes} MINUTE)


    AND ti.start_time BETWEEN #{startTime} AND #{endTime}


    AND ti.start_time  >= #{startTime}


    AND ti.start_time  <= #{endTime}


    AND ti.state = #{state}

SELECT ti.id AS taskInstanceId, ti.name AS taskName, ti.task_type AS taskType, ti.task_code AS taskCode, ti.process_instance_id AS processInstanceId, ti.process_instance_name AS processInstanceName, ti.state AS taskState, ti.start_time AS startTime, ti.submit_time AS submitTime, ti.end_time AS endTime, ti.retry_times AS retryTimes, TIMESTAMPDIFF(SECOND, ti.submit_time, NOW()) AS duration, task_avg.avg_duration AS avgDuration FROM t_ds_task_instance ti LEFT JOIN ( SELECT task_code, ROUND(AVG(TIMESTAMPDIFF(SECOND, submit_time, end_time))) AS avg_duration FROM t_ds_task_instance WHERE 1=1
AND start_time >= DATE_SUB(NOW(), INTERVAL #{intervalDay} DAY)
AND start_time >= DATE_SUB(NOW(), INTERVAL #{intervalMinutes} MINUTE)
AND start_time BETWEEN #{startTime} AND #{endTime}
AND start_time >= #{startTime}
AND start_time <= #{endTime}
AND state = 7 AND end_time IS NOT NULL AND submit_time IS NOT NULL GROUP BY task_code ) task_avg ON ti.task_code = task_avg.task_code WHERE 1=1
AND ti.start_time >= DATE_SUB(NOW(), INTERVAL #{intervalDay} DAY)
AND ti.start_time >= DATE_SUB(NOW(), INTERVAL #{intervalMinutes} MINUTE)
AND ti.start_time BETWEEN #{startTime} AND #{endTime}
AND ti.start_time >= #{startTime}
AND ti.start_time <= #{endTime}
AND ti.state = #{state}
ORDER BY ti.start_time DESC LIMIT #{pageSize} OFFSET #{offset}
